/* Version 9: focused broker workflows, read-first accounts and essential administration. */
function ensureV7(){
 if(!DB.v7){DB.v7={};const me=DB.users.find(u=>u.id==='u1');if(me)me.role='Agency Administrator';}
 DB.branches ||= [...new Set([...DB.accounts.map(a=>a.branch),...DB.users.map(u=>u.branch)].filter(Boolean))].map((name,i)=>({id:'branch'+i,name,status:'Active',email:'',phone:'',address:''}));
 DB.adminLog ||= [];
 for(const a of DB.accounts)for(const c of a.contacts||[]){c.officePhone??=c.phone||'';c.mobilePhone??='';c.preferredPhone??='Office';}
 for(const m of DB.markets)for(const c of m.contacts||[]){c.officePhone??=c.phone||'';c.mobilePhone??='';c.preferredPhone??='Office';}
}
const branchOptions=(current='')=>[...new Set([...DB.branches.filter(b=>b.status==='Active').map(b=>b.name),...(current?[current]:[])])];
function adminEvent(action,detail){DB.adminLog.unshift({id:makeId('audit'),at:now(),author:'Maria Alvarez',action,detail});}
function phoneLines(c={}){const office=c.officePhone??c.phone,mobile=c.mobilePhone;return `<div class="phone-lines">${office?`<span><small>Office</small> ${esc(office)}</span>`:''}${mobile?`<span><small>Mobile</small> ${esc(mobile)}</span>`:''}${!office&&!mobile?'—':''}</div>`;}
function contactNumbers(c={}){return field('Office phone','officePhone',c.officePhone??c.phone??'',{type:'tel',help:'Include the area code; extension is optional.'})+field('Mobile phone','mobilePhone',c.mobilePhone||'',{type:'tel'})+field('Preferred phone','preferredPhone',c.preferredPhone||'Office',{options:['Office','Mobile']});}
function checkPhones(v,required=false){const office=(v.officePhone||'').trim(),mobile=(v.mobilePhone||'').trim();if(required&&!office&&!mobile)return 'Add an office or mobile phone number.';for(const n of [office,mobile])if(n&&n.replace(/\D/g,'').length<7)return 'Enter a complete phone number, including the area code.';if((office||mobile)&&!(v.preferredPhone==='Mobile'?mobile:office))return 'Choose a preferred phone that has a number.';return '';}
function adminDenied(){toast('Open the administrator preview to change agency settings.',true);}
function v7Metrics(items){return `<div class="v7-metrics">${items.map(([label,value,note])=>`<div class="v7-metric"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('')}</div>`;}
const baseRenderV7=render;
render=function(){ensureV7();baseRenderV7();document.body.dataset.view=S.route[0];document.querySelectorAll('.navlink').forEach(a=>{a.title=a.getAttribute('aria-label');if(a.classList.contains('active'))a.setAttribute('aria-current','page');});const collapse=document.querySelector('[data-action="collapse"]');if(collapse){collapse.setAttribute('aria-label',S.collapsed?'Expand navigation':'Collapse navigation');collapse.setAttribute('aria-expanded',String(!S.collapsed));}document.querySelectorAll('form[data-form]').forEach(f=>{if(!f.querySelector('[data-save-state]')){const node=document.createElement('p');node.className='save-state';node.dataset.saveState='';node.setAttribute('aria-live','polite');node.textContent='';f.append(node);}});};
function dashboardView(){const pastDue=S.homeQueue!=='all';const ts=visibleTasks().filter(t=>pastDue?t.kind==='Task'&&t.status!=='Complete'&&t.due&&t.due<today():true).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));let ss=visibleSubs();const homeTasks=ts.filter(t=>match([t.title,t.description,accountName(t.accountId),subName(t.submissionId)].join(' '),S.filters.homeTasksQ)&&(!S.filters.homeTasksStatus||t.status===S.filters.homeTasksStatus));if(S.filters.homeTasksSort==='name')homeTasks.sort((a,b)=>a.title.localeCompare(b.title));ss=ss.filter(s=>match(s.name+' '+accountName(s.accountId),S.filters.homeSubsQ)&&(!S.filters.homeSubsStatus||s.status===S.filters.homeSubsStatus));if(S.filters.homeSubsSort==='name')ss.sort((a,b)=>a.name.localeCompare(b.name));else if(S.filters.homeSubsSort==='updated')ss.sort((a,b)=>(b.updated||'').localeCompare(a.updated||''));const taskPage=paginate(homeTasks,'homeTasks',6),subPage=paginate(ss,'homeSubs',6);const open=ss.filter(s=>!['Bound','Declined','Withdrawn'].includes(s.status));const quoted=ss.filter(s=>s.status==='Quoted');
 const kpi=(label,value,ic,clr,action,filter)=>`<div class="kpi"><div class="kpi-label"><span class="kpi-icon" style="color:${clr}">${icon(ic)}</span>${label}</div><div class="kpi-value" style="color:${clr}">${value}</div><small class="muted">${label==='Past-due tasks'?ts.filter(t=>t.due<today()).length+' overdue':label==='Quoted'?'awaiting a decision':'awaiting action'}</small></div>`;
 return titleBar('', 'Your workspace',new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'})+' · '+DB.agency.name,link('+ Create Account','#/accounts/new','btn')+act('+ Create Submission','start-submission',{},'btn primary'))+`<div class="kpis">${kpi('Past-due tasks',visibleTasks().filter(t=>t.kind==='Task'&&t.status!=='Complete'&&t.due&&t.due<today()).length,'clock','var(--brand)','go',{to:'#/tasks'})}${kpi('Open submissions',open.length,'submissions','#18181b','open-submissions',{})}${kpi('Quoted',quoted.length,'file','#7c3aed','quoted-submissions',{})}</div><div class="v8-home-tables stack"><section class="card"><div class="card-head"><h3 class="flex">${icon('check')} Tasks &amp; Notes</h3><div class="flex">${act('Past due','v7-queue',{filter:'overdue'},'btn small '+(pastDue?'primary':''))}${act('All tasks & notes','v7-queue',{filter:'all'},'btn small '+(!pastDue?'primary':''))}</div></div><div class="toolbar dashboard-table-tools">${filterSearch('homeTasksQ','Search tasks, notes or account…')}${filterSelect('homeTasksStatus',TASK_STATUSES,'All statuses')}${filterSelect('homeTasksSort',[['due','Due date'],['name','Name A–Z']],'Sort: due date')}${clearTableFiltersV9('homeTasks')}</div><div class="table-wrap"><table><thead><tr><th>Task / note</th><th>Account</th><th>Submission</th><th>Due</th><th>Priority</th><th>Status</th></tr></thead><tbody>${taskPage.items.map(t=>`<tr><td>${link(esc(t.title),'#/tasks/'+t.id,'td-name')}<div class="table-muted">${esc(t.kind)}</div></td><td>${link(esc(accountName(t.accountId)),'#/accounts/'+t.accountId)}</td><td>${t.submissionId?link(esc(subName(t.submissionId)),subHref(sub(t.submissionId))):'—'}</td><td class="${t.due<today()?'danger-text':''}">${t.kind==='Note'?'—':fmtDate(t.due)}</td><td>${t.kind==='Note'?'—':badge(t.priority)}</td><td>${t.kind==='Note'?'—':badge(t.status)}</td></tr>`).join('')||'<tr><td colspan="6">No matching items. Clear filters or choose All tasks & notes.</td></tr>'}</tbody></table></div>${pager(taskPage,'items')}<div class="card-foot center">${link('View all tasks & notes →','#/tasks','link small')}</div></section><section class="card"><div class="card-head"><h3 class="flex">${icon('submissions')} Submissions</h3></div><div class="toolbar dashboard-table-tools">${filterSearch('homeSubsQ','Search submissions or account…')}${filterSelect('homeSubsStatus',STATUSES,'All statuses')}${filterSelect('homeSubsSort',[['name','Name A–Z'],['updated','Recently updated']],'Sort: original order')}${clearTableFiltersV9('homeSubs')}</div><div class="table-wrap"><table><thead><tr><th>Submission</th><th>Account</th><th>Lines of business</th><th>Producer</th><th>CSR</th><th>Status</th></tr></thead><tbody>${subPage.items.map(s=>`<tr><td>${link(esc(s.name),subHref(s),'td-name')}</td><td>${link(esc(accountName(s.accountId)),'#/accounts/'+s.accountId)}</td><td style="min-width:155px">${lobList(s.lobs)}</td><td>${person(s.producer)}</td><td class="nowrap">${esc(s.csr)}</td><td>${badge(s.status)}</td></tr>`).join('')||'<tr><td colspan="6">No submissions match these filters.</td></tr>'}</tbody></table></div>${pager(subPage,'submissions')}<div class="card-foot center">${link('View all submissions →','#/submissions','link small')}</div></section></div><section class="card mt"><div class="card-head"><h3>Activity</h3><small class="muted">All agency actions</small></div><div class="card-body">${DB.logs.filter(l=>branchVisible(account(l.accountId))).slice(0,7).map(l=>`<div class="flex" style="padding:12px 0;border-bottom:1px solid #f1f1f3">${avatar(l.author)}<div><div>${esc(l.author)} · ${l.submissionId?link(esc(l.description),subHref(sub(l.submissionId)),'link'):link(esc(l.description),'#/accounts/'+l.accountId+'/log','link')}</div><small class="muted">${stamp(l.at)}</small></div></div>`).join('')}</div></section>`;
}
const baseAccountsV7=accountsView,baseEditorV7=accountEditor;
accountsView=function(id,tab='overview',detail){
 if(id==='new'||!id||tab!=='overview')return baseAccountsV7(id,tab,detail);
 const a=account(id);if(!a)return baseAccountsV7(id,tab,detail);
 if(S.editingAccount===id)return pageBreadcrumbs([['Accounts','#/accounts'],[a.name,'#/accounts/'+id],['Edit account']])+titleBar('','Edit '+a.name,'Update the details below, then save your changes.')+accountEditor(a,true);
 const openTasks=accountTasks(id).filter(t=>t.kind==='Task'&&t.status!=='Complete');const subs=accountSubs(id);
 const detailRow=(label,value)=>`<div class="detail-pair"><dt>${label}</dt><dd>${esc(value||'Not added')}</dd></div>`;
 return pageBreadcrumbs([['Accounts','#/accounts'],[a.name]])+titleBar('',a.name,a.description,act('Edit account','v7-edit-account',{id},'btn')+act('+ New submission','start-submission',{accountId:id},'btn primary'))+`<div class="record-meta">${badge(a.type)}<span>Producer · ${esc(a.producer)}</span><span>CSR · ${esc(a.csr||'Unassigned')}</span><span>Updated ${fmtDate(a.updated)}</span></div><nav class="tabs" aria-label="Account sections">${[['overview','Overview'],['submissions','Submissions ('+subs.length+')'],['tasks','Tasks & Notes'],['documents','Documents'],['log','Activity']].map(([k,l])=>link(l,'#/accounts/'+id+'/'+k,'tab '+(k===tab?'active':''))).join('')}</nav><div class="v7-record-grid"><div class="stack"><section class="card"><div class="card-head"><h2>Business details</h2></div><dl class="detail-grid">${detailRow('Business type',naicsLabel(a.naics))}${detailRow('Legal entity',a.entity)}${detailRow('Primary address',[a.street,a.city,a.state,a.zip].filter(Boolean).join(', '))}${detailRow('Mailing address',[a.mailingAddress?.street,a.mailingAddress?.city,a.mailingAddress?.state,a.mailingAddress?.zip].filter(Boolean).join(', '))}${detailRow('FEIN',a.fein)}${detailRow('Lead source',a.lead)}${detailRow('Category',a.category)}</dl></section><section class="card"><div class="card-head"><div><h2>People to contact</h2><p class="subtitle small">Office and mobile numbers kept separately.</p></div></div><div class="contact-read-list">${a.contacts.map(c=>`<article class="contact-read"><div class="between"><div><h3>${esc(c.name)}</h3><small class="muted">${esc(c.role)}</small></div>${c.primary?'<span class="pill green">Primary</span>':''}</div>${phoneLines(c)}<a class="contact-email" href="mailto:${esc(c.email)}">${esc(c.email)}</a>${c.officePhone||c.mobilePhone?`<small class="muted">Prefers ${esc((c.preferredPhone||'Office').toLowerCase())} calls</small>`:''}</article>`).join('')}</div></section><section class="card"><div class="card-head"><h2>Account Notes</h2>${act('Edit notes','v8-edit-notes',{id},'btn small')}</div><p class="read-notes">${esc(a.notes||'No account notes yet. Add information you want to keep with this account.')}</p></section></div><aside class="stack">${accountWidgetsV8(id)}</aside></div>`;
};
const oldAccountsTableV7=accountsTable;
accountsTable=function(){let rows=DB.accounts.filter(a=>!a.archived&&branchVisible(a)&&match(a.name+' '+(primaryContact(a)?.name||'')+' '+(primaryContact(a)?.email||'')+' '+a.naics+' '+naicsLabel(a.naics)+' '+(primaryContact(a)?.officePhone||'')+' '+(primaryContact(a)?.mobilePhone||''),S.filters.accountsQ)&&(!S.filters.accountsType||a.type===S.filters.accountsType)&&(!S.filters.accountsProducer||a.producer===S.filters.accountsProducer));rows.sort((a,b)=>S.filters.accountsSort==='updated'?b.updated.localeCompare(a.updated):a.name.localeCompare(b.name));const p=paginate(rows,'accounts',10);return titleBar('','Accounts','Find the right business and pick up the conversation.',act('Export','export-accounts',{},'btn')+link('+ New account','#/accounts/new','btn primary'))+`<div class="toolbar">${filterSearch('accountsQ','Search business, contact or email…')}${filterSelect('accountsProducer',PRODUCERS,'All producers')}${filterSelect('accountsType',[...new Set(DB.accounts.map(a=>a.type))],'All account types')}<select data-filter="accountsSort" aria-label="Sort accounts">${options([['name','Name A–Z'],['updated','Recently updated']],S.filters.accountsSort||'name')}</select>${S.filters.accountsQ||S.filters.accountsProducer||S.filters.accountsType||S.filters.accountsSort?act('Clear filters','v7-clear-accounts',{},'btn ghost'):''}<span class="grow"></span><span class="muted small">${rows.length} accounts</span></div><section class="card"><div class="table-wrap"><table class="v7-accounts-table"><thead><tr><th>Business</th><th>Primary contact</th><th>Phone numbers</th><th>Owner</th><th>Open submissions</th><th></th></tr></thead><tbody>${p.items.map(a=>{const c=primaryContact(a)||{};return `<tr><td>${link(esc(a.name),'#/accounts/'+a.id,'td-name')}<div class="table-muted">${esc(a.city)}, ${esc(a.state)} · ${esc(a.type)}</div></td><td>${esc(c.name||'Not added')}<div class="table-muted">${esc(c.email||'')}</div></td><td>${phoneLines(c)}</td><td>${esc(a.producer)}</td><td>${accountSubs(a.id).filter(s=>!['Bound','Declined','Withdrawn'].includes(s.status)).length}</td><td>${link('Open →','#/accounts/'+a.id,'link small')}</td></tr>`;}).join('')||`<tr><td colspan="6">${empty('No matching accounts','Try another search or clear your filters.',act('Clear filters','v7-clear-accounts',{},'btn'))}</td></tr>`}</tbody></table></div>${pager(p,'accounts')}</section>`;};
function adminView(tab='agency',id){if(S.role!=='Admin')return empty('Administrator access required','Agency settings are available in the administrator preview.');const body=tab==='users'?usersView():tab==='roles'?rolesView():tab==='markets'?(id?marketEditor(id):marketDirectory()):tab==='activity'?adminActivityV7():tab==='data'?adminDataV7():agencyView();return titleBar('','Agency settings','Manage your agency details, users and access.')+`<div class="admin-layout"><div class="admin-main">${body}</div></div>`;}
function agencyView(){const a=DB.agency;return `<form data-form="agency"><div class="sectionhead"><h2>Agency details</h2><p class="subtitle">Your business identity and the contact information your users use.</p></div><section class="card"><div class="card-head"><h3>Business & contact</h3></div><div class="card-body form-grid">${field('Agency name','name',a.name,{required:true})}${field('Agency email','email',a.email,{type:'email',required:true})}${field('Office phone','phone',a.phone,{type:'tel',required:true})}${field('Website','website',a.website,{type:'url',placeholder:'https://example.com'})}${field('Primary contact','contact',a.contact,{required:true})}${field('Mobile phone','mobilePhone',a.mobilePhone,{type:'tel'})}${field('Mailing address','address',a.address,{wide:true,required:true})}</div></section><div class="wizard-nav"><span class="muted small">Changes apply to this agency.</span><button type="submit" class="btn primary">Save agency details</button></div></form>`;}
function usersView(){const rows=DB.users.filter(u=>match(u.name+' '+u.email,S.filters.userQ)&&(!S.filters.userStatus||u.status===S.filters.userStatus)&&(!S.filters.userRole||u.role===S.filters.userRole));rows.sort((a,b)=>S.filters.userSort==='status'?a.status.localeCompare(b.status)||a.name.localeCompare(b.name):a.name.localeCompare(b.name));const p=paginate(rows,'user',10);return `<div class="between sectionhead"><div><h2>Users</h2><p class="subtitle">Manage users and their access.</p></div>${act('+ Invite user','edit-user',{},'btn primary')}</div><div class="toolbar">${filterSearch('userQ','Search name or email…')}${filterSelect('userStatus',['Active','Invited','Inactive'],'All statuses')}${filterSelect('userRole',['Agency Administrator','Producer / CSR'],'All roles')}${filterSelect('userSort',[['name','Name A–Z'],['status','Status']],'Sort: name')}${clearTableFiltersV9('user')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody>${p.items.map(u=>`<tr><td><strong>${esc(u.name)}</strong>${u.id==='u1'?'<span class="pill v7-you">You</span>':''}<div class="table-muted">${esc(u.email)}</div></td><td>${esc(u.role)}</td><td>${badge(u.status)}</td><td><div class="flex">${act('Edit','edit-user',{id:u.id},'btn small')}${u.status==='Invited'?act('Prepare invite','v7-invite',{id:u.id},'btn small'):''}</div></td></tr>`).join('')||'<tr><td colspan="4">'+empty('No matching users','Try another name or change the filters.')+'</td></tr>'}</tbody></table></div>${pager(p,'users')}<div class="card-foot muted small">${rows.length} users · Invitations and password resets are previews; no email is sent.</div></section>`;}
function userModal(id){const u=DB.users.find(u=>u.id===id)||{};openModal(id?'Edit user':'Invite user',`<div class="form-grid">${field('Full name','name',u.name,{required:true})}${field('Email','email',u.email,{type:'email',required:true})}${field('Role','role',u.role||'Producer / CSR',{options:['Agency Administrator','Producer / CSR']})}${id?field('Status','status',u.status,{options:['Active','Invited','Inactive']}):'<input type="hidden" name="status" value="Invited">'}</div><div class="info mt">${id?'Deactivating a user keeps their history. Reassign any open work first. You cannot remove your own administrator access.':'An invitation record will be created. Actual email delivery will be connected in a later phase.'}</div>`,(id?act('Password reset preview','reset-user-password',{id},'btn user-reset-password'):'')+act('Cancel','close-modal')+'<button class="btn primary" type="submit">'+(id?'Save user':'Create invitation')+'</button>',{form:'user',data:{id:id||''}});}
function resetUserPassword(id){const u=DB.users.find(u=>u.id===id);if(!canAccess('settings')||!u)return adminDenied();adminEvent('Password reset preview',u.name+' · No email sent');persist();openModal('Password reset preview',`<p>A reset link would be sent to <strong>${esc(u.email)}</strong> once email and sign-in are connected.</p><p class="info mt">No email has been sent and no password has changed.</p>`,act('Done','close-modal',{},'btn primary'),{stack:true});}
function rolesView(){return `<div class="sectionhead"><h2>Roles & Permissions</h2><p class="subtitle">Define what each role can access</p></div><section class="card">${['Agency Administrator','Producer / CSR'].map(r=>`<div class="between" style="padding:24px;border-bottom:1px solid var(--line)"><div><h3>${r}</h3><p class="subtitle small">${r==='Agency Administrator'?'Full access to all settings, users and data':'Manage accounts, submissions and tasks; no Admin Settings access'}</p></div>${act('Edit','edit-permissions',{role:r},'btn small')}</div>`).join('')}</section>`;}
function adminActivityV7(){const rows=DB.adminLog.filter(l=>match(l.action+' '+l.detail+' '+l.author,S.filters.adminAuditQ));return `<div class="sectionhead"><h2>Admin system log</h2><p class="subtitle">Saved agency, user and access changes in this prototype. This is not a complete security audit log.</p></div><div class="toolbar">${filterSearch('adminAuditQ','Search changes…')}</div><section class="card">${rows.slice(0,100).map(l=>`<div class="activity-row">${icon('clock')}<div class="grow"><strong>${esc(l.action)}</strong><p>${esc(l.detail)}</p><small>${esc(l.author)} · ${stamp(l.at)}</small></div></div>`).join('')||empty('No changes to show','Saved settings changes will appear here.')}<div class="card-foot muted small">${rows.length} matching changes${rows.length>100?' · Showing the latest 100':''}</div></section>`;}
function adminDataV7(){return `<div class="sectionhead"><h2>Prototype data</h2><p class="subtitle">Optional testing tools for this local prototype. These are not agency backup tasks.</p></div><section class="card pad"><h3>Download a backup</h3><p class="subtitle mb">Download a JSON file containing the current sample records and uploaded file data. Use it to keep or move your prototype test work; it is not an automatic or cloud backup.</p>${act('Download backup','export-data',{},'btn primary')}</section><section class="card pad mt"><h3>Restore a backup</h3><p class="subtitle mb">Restoring replaces the records in this version. Download a backup first if you need to keep your current work.</p>${act('Choose backup file','v7-restore',{},'btn')}</section><section class="card pad mt"><h3>Start over with sample data</h3><p class="subtitle mb">Clear changes in version 9 and return to the sample agency. Earlier versions stay separate.</p>${act('Reset version 9','reset-demo',{},'btn danger')}</section><p class="muted small mt">This is local browser storage, not a shared cloud backup. Keep downloaded files somewhere you trust.</p>`;}
const baseActionV7=handleAction;
handleAction=async function(action,d,el){
 if(['edit-user','reset-user-password','edit-permissions','v7-branch','v7-invite','v7-restore','reset-demo','import-data','export-data'].includes(action)&&S.role!=='Admin')return adminDenied();
 if(action==='v7-queue'){S.filters.homeTasksPage=1;S.homeQueue=d.filter;return render();}
 if(action==='v7-clear-accounts'){delete S.filters.accountsQ;delete S.filters.accountsProducer;delete S.filters.accountsType;delete S.filters.accountsSort;S.filters.accountsPage=1;return render();}
 if(action==='v7-edit-account'||action==='v7-edit-contacts'){S.editingAccount=d.id;if(action==='v7-edit-contacts'){S.accountSections||={};S.accountSections[d.id+'-contacts']=true;}render();if(action==='v7-edit-contacts')document.querySelector('[data-account-section="'+d.id+'-contacts"]')?.scrollIntoView({block:'start'});return;}
 if(action==='cancel-account'){S.editingAccount=null;S.v7Dirty=false;}
 if(action==='close-modal'&&document.querySelector('#modal-root form[data-form="user"],#modal-root form[data-form="v7-branch"]'))S.v7Dirty=false;
 if(['v7-branch','branches','switch-branch'].includes(action))return;

 if(action==='v7-invite'){const u=DB.users.find(u=>u.id===d.id);if(!u)return;adminEvent('Invitation prepared',u.name+' · No email sent');persist();return openModal('Invitation preview',`<p><strong>${esc(u.name)}</strong> will be invited at ${esc(u.email)} as ${esc(u.role)}.</p><p class="info mt">No email has been sent. This phase stores the invitation record only.</p>`,act('Done','close-modal',{},'btn primary'));}
 if(action==='v7-restore')return confirmAction('Replace version 9 records?','Choose a backup after confirming. Current records will be replaced only if the file passes validation.',()=>baseActionV7('import-data',{},el),'Choose backup');

 return baseActionV7(action,d,el);
};
const baseFormV7=handleForm;
handleForm=async function(form){const name=form.dataset.form,v=readForm(form),id=form.dataset.id;
 if(['agency','user','permissions','v7-branch','market','market-contact','market-lob'].includes(name)&&S.role!=='Admin')return adminDenied();
 if(name==='user'){
  v.name=v.name.trim();v.email=v.email.trim().toLowerCase();if(!v.name)return toast('Enter a full name.',true);
  if(DB.users.some(u=>u.id!==id&&u.email.toLowerCase()===v.email))return toast('This email already belongs to a user.',true);
  const old=DB.users.find(u=>u.id===id);v.branch=old?.branch||'';
  if(old?.id==='u1'&&(v.role!=='Agency Administrator'||v.status!=='Active'))return toast('You cannot remove your own administrator access.',true);
  if(old?.role==='Agency Administrator'&&old.status==='Active'&&(v.role!=='Agency Administrator'||v.status!=='Active')&&!DB.users.some(u=>u.id!==id&&u.role==='Agency Administrator'&&u.status==='Active'))return toast('Keep at least one active administrator.',true);
  if(old&&v.status!=='Active'&&old.status==='Active'){const key=old.short||old.name;const count=DB.tasks.filter(t=>t.kind==='Task'&&t.status!=='Complete'&&t.assignee===key).length+DB.subs.filter(s=>!['Bound','Declined','Withdrawn'].includes(s.status)&&(s.producer===key||s.csr===key)).length+DB.accounts.filter(a=>!a.archived&&(a.producer===key||a.csr===key)).length;if(count)return toast('Reassign this user’s '+count+' account, submission or open task assignments first.',true);}
  const save=()=>{if(old)Object.assign(old,v);else DB.users.push({...v,id:makeId('user'),short:v.name});adminEvent(old?'User updated':'Invitation created',v.name+' · '+v.role+' · '+v.status);S.v7Dirty=false;persist();closeModal();render();toast(old?'User saved':'Invitation recorded — no email sent');};
  if(old&&old.status==='Active'&&v.status!=='Active')return confirmAction('Deactivate '+old.name+'?','Their history will stay available. New work should be assigned to another active user.',save,'Deactivate',true);return save();
 }
 if(name==='v7-branch')return;
 if(name==='market-contact'){const message=checkPhones(v);if(message)return toast(message,true);}
 if(name==='agency'){v.name=v.name.trim();if(!v.name)return toast('Enter the agency name.',true);adminEvent('Agency details updated',v.name);}
 if(name==='permissions')adminEvent('Role access updated',form.dataset.role);
 
 await baseFormV7(form);
};
const baseSaveAccountV7=saveAccountForm;
saveAccountForm=function(form){const invalid=$$('input[name$=".officePhone"]',form).some(el=>{const prefix=el.name.replace('officePhone','');const v={officePhone:el.value,mobilePhone:form.elements.namedItem(prefix+'mobilePhone').value,preferredPhone:form.elements.namedItem(prefix+'preferredPhone').value};const msg=checkPhones(v,true);if(msg){el.closest('details').open=true;toast(msg,true);el.focus();return true;}return false;});if(invalid)return;const before=DB.logs.length;baseSaveAccountV7(form);if(DB.logs.length>before){S.editingAccount=null;S.v7Dirty=false;render();}};
const baseCaptureAccountV7=captureAccountDraft;
captureAccountDraft=function(form){const d=baseCaptureAccountV7(form);const v=readForm(form);if(v.branch)d.branch=v.branch;d.contacts.forEach((c,i)=>{for(const k of ['officePhone','mobilePhone','preferredPhone'])c[k]=v['contact.'+i+'.'+k]??c[k];c.phone=c.preferredPhone==='Mobile'?c.mobilePhone:c.officePhone;});return d;};
const baseGetDraftV7=getAccountDraft;
getAccountDraft=function(a){const d=baseGetDraftV7(a);for(const c of d.contacts){c.officePhone??=c.phone||'';c.mobilePhone??='';c.preferredPhone??='Office';}return d;};
const baseSaveMarketContactV7=saveMarketContact;
saveMarketContact=function(form){baseSaveMarketContactV7(form);const ctx=S.marketContactContext;const m=S.drafts['market-'+ctx.mid];for(const c of m?.contacts||[])c.phone=c.preferredPhone==='Mobile'?c.mobilePhone:c.officePhone;if(ctx.quoteContext){market(ctx.mid).contacts=clone(m.contacts);persist();}};
// Show a gentle save reminder only after a field is changed.
document.addEventListener('input',e=>{const f=e.target.closest('form[data-form]');if(!f||!['account','agency','user','v7-branch','market'].includes(f.dataset.form))return;S.v7Dirty=true;const n=f.querySelector('[data-save-state]');if(n)n.textContent='You have unsaved changes.';});
window.addEventListener('beforeunload',e=>{if(S.v7Dirty){e.preventDefault();e.returnValue='';}});
const initialPeopleV7={people:[...PEOPLE],producers:[...PRODUCERS],csrs:[...CSRS]};
syncAssignees=function(){const inactive=new Set(DB.users.filter(u=>u.status==='Inactive').map(u=>u.short||u.name));const active=DB.users.filter(u=>u.status==='Active').map(u=>u.short||u.name);for(const [list,base] of [[PEOPLE,initialPeopleV7.people],[PRODUCERS,initialPeopleV7.producers],[CSRS,initialPeopleV7.csrs]])list.splice(0,list.length,...new Set([...base,...active].filter(n=>!inactive.has(n))));};
const baseSaveMarketV7=saveMarket;
saveMarket=function(form){const id=form.dataset.id,name=form.elements.namedItem('name').value;baseSaveMarketV7(form);if(!S.drafts['market-'+id]){S.v7Dirty=false;adminEvent('Market saved',name);persist();}};
// Ask before leaving an edited settings or account form; ordinary navigation stays immediate.
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#/"]');const cancel=e.target.closest('[data-action="cancel-account"],[data-action="cancel-market"]');if(!S.v7Dirty||(!a&&!cancel)||a?.getAttribute('href')===location.hash)return;e.preventDefault();e.stopImmediatePropagation();const destination=a?.getAttribute('href')||(S.route[0]==='admin'?'#/admin/markets':'#/accounts/'+(S.route[1]==='new'?'':S.route[1]));confirmAction('Leave without saving?','Your unsaved field changes will be discarded. Stay here to save them first.',()=>{S.v7Dirty=false;S.editingAccount=null;S.drafts={};nav(destination);},'Leave without saving');},true);

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('#modal-root form[data-form="user"],#modal-root form[data-form="v7-branch"]'))S.v7Dirty=false;},true);
function agencyNavigationV7(){const current=['overview','branches'].includes(S.route[1])?'agency':S.route[1]||'agency',expanded=S.settingsExpanded??S.route[0]==='admin';const items=[['agency','Agency Details'],['users','Users'],['roles','Roles & Access'],['markets','Carriers & Markets'],['activity','Admin System Log'],['data','Prototype Data']];return `<div class="agency-nav-group"><button type="button" class="navlink agency-nav-toggle ${S.route[0]==='admin'?'section-active':''}" data-action="v7-settings-toggle" aria-label="Agency Settings" aria-expanded="${expanded}" aria-controls="agency-subnav" title="Agency Settings">${icon('settings')}<span class="nav-text">Agency Settings</span><span class="agency-nav-chevron" aria-hidden="true">${expanded?'⌃':'⌄'}</span></button><nav id="agency-subnav" class="agency-subnav" aria-label="Agency Settings sections" ${expanded?'':'hidden'}>${items.map(([k,label])=>`<a href="#/admin/${k}" ${S.route[0]==='admin'&&current===k?'aria-current="page"':''} class="${S.route[0]==='admin'&&current===k?'active':''}">${label}</a>`).join('')}</nav></div>`;}
const shellBeforeSidebarV7=shell;
shell=function(body){return shellBeforeSidebarV7(body).replace('<div class="app ', '<div class="app '+(S.settingsRailOpen?'settings-rail-open ':'')).replace(/<a class="navlink [^"]*" href="#\/admin" aria-label="Agency settings">[\s\S]*?<\/a>/,agencyNavigationV7()).replace('<span>Broker portal</span>','<span>Broker Portal</span>');};
const actionBeforeSidebarV7=handleAction;
handleAction=async function(action,d,el){if(action==='v7-settings-toggle'){S.settingsExpanded=!(S.settingsExpanded??S.route[0]==='admin');if(S.collapsed||(innerWidth>=768&&innerWidth<=1023&&!S.settingsRailOpen)){S.collapsed=false;S.settingsExpanded=true;document.querySelector('.app')?.classList.remove('collapsed');const c=document.querySelector('[data-action="collapse"]');c?.setAttribute('aria-label','Collapse navigation');c?.setAttribute('aria-expanded','true');}S.settingsRailOpen=true;document.querySelector('.app')?.classList.add('settings-rail-open');document.querySelector('.agency-nav-group').outerHTML=agencyNavigationV7();return;}if(action==='collapse'){S.collapsed=!S.collapsed;document.querySelector('.app')?.classList.toggle('collapsed',S.collapsed);el?.setAttribute('aria-label',S.collapsed?'Expand navigation':'Collapse navigation');el?.setAttribute('aria-expanded',String(!S.collapsed));persist();return;}if(action==='mobile-nav'){S.mobileNav=!S.mobileNav;document.querySelector('.app')?.classList.toggle('mobile-nav-open',S.mobileNav);el?.setAttribute('aria-expanded',String(S.mobileNav));return;}return actionBeforeSidebarV7(action,d,el);};
const renderBeforeSidebarV7=render;
render=function(){if(location.hash.startsWith('#/admin')&&location.hash!==S.lastRenderedRoute)S.settingsExpanded=true;return renderBeforeSidebarV7();};
